import{_ as t,H as o,f as r,i as a}from"./chunks/framework.DLd0CbzH.js";const p=JSON.parse('{"title":"About the Developers","description":"The story behind OmniCraft ERP, the philosophy of craft, and contacts for the N. Murashkin workshop.","frontmatter":{"title":"About the Developers","description":"The story behind OmniCraft ERP, the philosophy of craft, and contacts for the N. Murashkin workshop.","order":18},"headers":[],"relativePath":"docs/about.md","filePath":"docs/about.md"}'),n={name:"docs/about.md"};function s(i,e,c,h,l,d){return o(),r("div",null,[...e[0]||(e[0]=[a('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="🛠️-about-the-developers-from-workbench-to-code" tabindex="-1">🛠️ About the Developers: From Workbench to Code <a class="header-anchor" href="#🛠️-about-the-developers-from-workbench-to-code" aria-label="Permalink to &quot;🛠️ About the Developers: From Workbench to Code&quot;">​</a></h1><p><strong>OmniCraft ERP</strong> is not the product of a faceless tech corporation or another venture-funded cloud subscription. This program was born amidst the dust and scent of genuine leather, under the rhythmic strike of a mallet and the hum of sewing machines.</p><p>The system is developed by the <strong>N. Murashkin Leather Workshop</strong>.</p><p>🌐 <strong>Workshop Website:</strong> <a href="https://nmurashkin.ru" target="_blank" rel="noreferrer">nmurashkin.ru</a></p><hr><h2 id="🧵-philosophy-of-craft-and-code" tabindex="-1">🧵 Philosophy of Craft and Code <a class="header-anchor" href="#🧵-philosophy-of-craft-and-code" aria-label="Permalink to &quot;🧵 Philosophy of Craft and Code&quot;">​</a></h2><p>In our workshop, we follow a strict rule: <strong>to create items that will bring joy to their owners for decades</strong>. We do not chase fast fashion or disposable goods. Each bag, wallet, or passport cover is engineered for long-term service, utilizing top-grade leather and robust hardware.</p><p>We have carried this same philosophy of &quot;enduring value&quot; into our software development. OmniCraft ERP was created as <strong>a tool for life</strong> for the artisan. We believe that business accounting software should be:</p><ul><li><strong>Reliable:</strong> Like a strong stitch with waxed thread, the software must not tear when you need it most. Our database architecture (WAL-journaling, GFS-backups) ensures the safety of your metrics.</li><li><strong>Independent:</strong> Your data belongs entirely to you. That is why OmniCraft works locally on your computer (Local-First), requires no constant internet connection, and never transmits your financial secrets to external servers.</li><li><strong>Honest:</strong> We do not force you to maintain bookkeeping records just for the sake of it. The program speaks to you in the language of business logic, cost prices, and your return on time (Time ROI).</li></ul><hr><h2 id="💡-why-we-created-omnicraft-erp" tabindex="-1">💡 Why We Created OmniCraft ERP <a class="header-anchor" href="#💡-why-we-created-omnicraft-erp" aria-label="Permalink to &quot;💡 Why We Created OmniCraft ERP&quot;">​</a></h2><p>Before this program was created, our workshop records were scattered across cumbersome Excel spreadsheets, notebooks, and disconnected applications. Every time we needed to calculate the exact cost of a backpack—taking into account leather shipping, tool wear, and hours spent—it required tens of minutes of redundant math.</p><p>We realized that an artisan needs something different:</p><ol><li><strong>Friction-Free Automation:</strong> The program itself should calculate the MAC-based cost price of materials, allocate shipping, and calculate depreciation.</li><li><strong>Understanding Efficiency:</strong> The master needs to see more than just &quot;income and expenses&quot;; they need to understand <em>Time ROI</em> (return on time) and their monthly break-even point.</li><li><strong>Freedom from the Cloud:</strong> We wanted to be sure that our service would never shut down overnight, raise prices tenfold, or lock us out of our own client database.</li></ol><p>Thus, OmniCraft was born—a smart ERP built by crafters, for crafters (and any other business-minded artisans).</p><hr><h2 id="🤝-feedback-and-community" tabindex="-1">🤝 Feedback and Community <a class="header-anchor" href="#🤝-feedback-and-community" aria-label="Permalink to &quot;🤝 Feedback and Community&quot;">​</a></h2><p>We continue to develop the project, relying on our own workshop practice and the needs of our fellow craftsmen.</p><p>If you find a bug, want to suggest a new feature (such as a specific module for ceramics or woodworking), or simply want to share your thoughts—we are always here.</p><ul><li><strong>Website &amp; Documentation:</strong> <a href="https://omnicraft-erp.com" target="_blank" rel="noreferrer">omnicraft-erp.com</a></li><li><strong>Releases Repository (GitHub):</strong> <a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noreferrer">OmniCraft-ERP-Releases</a></li><li><strong>N. Murashkin Workshop:</strong> <a href="https://nmurashkin.ru" target="_blank" rel="noreferrer">nmurashkin.ru</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Gratitude</p><p>Thank you for choosing OmniCraft ERP. We hope this software lifts the burden of routine and gives you back your most valuable asset—<strong>time</strong>. Time for creativity, for family, and for creating things that stand the test of time.</p></div>',23)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
